(root/'src/main/core/applications/__tests__/terminal-insertion.test.ts').write_text(r'''import {randomUUID} from 'node:crypto';
import {beforeEach,afterEach,describe,it,expect,vi} from 'vitest';
import {ApplicationTerminalInsertion,type ApplicationTerminalProof} from '../terminal-insertion';
import type {ApplicationUiSender} from '../execution-context';
import type {ApplicationTerminalBind} from '@shared/application-terminal';
import {PtyAccess} from '../../../pty-access';
const sender=()=>{const frame={};return{sender:{id:1,mainFrame:frame,isDestroyed:()=>false},senderFrame:frame} as unknown as ApplicationUiSender;};
let service:ApplicationTerminalInsertion,owner:ApplicationUiSender,other:ApplicationUiSender,pty:string|null,now:number,writes:{id:string;data:string}[],proof:ApplicationTerminalProof,resolve:ReturnType<typeof vi.fn>,bracketed:ReturnType<typeof vi.fn>;
const target={taskId:'task1',ptyId:'pty1'},input=():ApplicationTerminalBind=>({projectId:'project1',target,source:{kind:'skill',appId:'mail',skillId:'work-assistant'}});
beforeEach(()=>{owner=sender();other=sender();pty='pty1';now=1000;writes=[];proof={runId:'owned-run',text:'reference\nsecond\x1b[201~\x00\u202e',assert:vi.fn(),inspect:vi.fn(async()=>{})};resolve=vi.fn(async()=>proof);bracketed=vi.fn(async()=>false);const access=new PtyAccess({trusted:e=>e.sender===owner.sender,activePty:()=>pty,alive:id=>id===pty,write:()=>{},resize:()=>{},killTask:()=>{}});service=new ApplicationTerminalInsertion({requireSender:e=>access.requireSender(e),authorize:(e,t)=>{access.authorize(e,t);},resolve,bracketedPaste:bracketed,write:(id,data)=>writes.push({id,data}),now:()=>now});});
afterEach(()=>service.dispose());
describe('sender-owned application terminal insertion',()=>{
 it('rejects another renderer,foreign frame,wrong PTY and client-supplied text before source preparation',async()=>{await expect(service.bind(other,input())).rejects.toThrow();await expect(service.bind({...owner,senderFrame:other.senderFrame},input())).rejects.toThrow();await expect(service.bind(owner,{...input(),target:{...target,ptyId:'other'}})).rejects.toThrow();await expect(service.bind(owner,{...input(),text:'client-command'} as never)).rejects.toThrow();expect(resolve).not.toHaveBeenCalled();expect(writes).toEqual([]);});
 it('formats a bounded paste,never writes an Enter,and reuses the same operation exactly once',async()=>{const b=await service.bind(owner,input()),request={bindingId:b.id,operationId:randomUUID()};const [a,c]=await Promise.all([service.insert(owner,request),service.insert(owner,request)]);expect(a).toEqual(c);expect(a).toMatchObject({state:'inserted',bracketed:false});expect(writes).toEqual([{id:'pty1',data:'reference second[201~'}]);await expect(service.insert(owner,{...request,operationId:randomUUID()})).rejects.toMatchObject({code:'RESOURCE_STATE_CHANGED'});expect(writes).toHaveLength(1);});
 it('uses actual mode framing but strips attempted paste terminators from the body',async()=>{bracketed.mockResolvedValue(true);const b=await service.bind(owner,input());await service.insert(owner,{bindingId:b.id,operationId:randomUUID()});expect(writes[0].data).toBe('\x1b[200~reference\rsecond[201~\x1b[201~');expect(writes[0].data.endsWith('\r')).toBe(false);});
 it('revalidates policy after asynchronous paste-mode observation before a write',async()=>{let finish!:(v:boolean)=>void;bracketed.mockImplementation(()=>new Promise<boolean>(r=>finish=r));const b=await service.bind(owner,input()),pending=service.insert(owner,{bindingId:b.id,operationId:randomUUID()});await vi.waitFor(()=>expect(bracketed).toHaveBeenCalled());proof.assert=()=>{throw new Error('binding revoked');};finish(false);expect(await pending).toMatchObject({state:'failed',message:'binding revoked'});expect(writes).toEqual([]);});
 it.each(['release','pty','policy','dispose'] as const)('a pending source check cannot deliver after %s changes',async change=>{let finish!:()=>void;proof.inspect=()=>new Promise<void>(r=>finish=r);const b=await service.bind(owner,input()),pending=service.insert(owner,{bindingId:b.id,operationId:randomUUID()});if(change==='release')service.release(owner,b.id);if(change==='pty')pty='replacement';if(change==='policy')proof.assert=()=>{throw new Error('policy changed');};if(change==='dispose')service.dispose();finish();expect(await pending).toMatchObject({state:'failed'});expect(writes).toEqual([]);});
 it('does not let late preparation replace the newer binding in the same frame',async()=>{let finish!:(v:ApplicationTerminalProof)=>void;resolve.mockImplementationOnce(()=>new Promise<ApplicationTerminalProof>(r=>finish=r));const old=service.bind(owner,input()),next=await service.bind(owner,input());finish(proof);await expect(old).rejects.toMatchObject({code:'CANCELED'});expect(await service.insert(owner,{bindingId:next.id,operationId:randomUUID()})).toMatchObject({state:'inserted'});expect(writes).toHaveLength(1);});
 it('keeps an ambiguous native write unknown and never writes it again',async()=>{service.dispose();const write=vi.fn(()=>{throw new Error('partial native acceptance');});service=new ApplicationTerminalInsertion({requireSender:()=>{},authorize:()=>{},resolve:async()=>proof,bracketedPaste:async()=>false,write});const b=await service.bind(owner,input()),op={bindingId:b.id,operationId:randomUUID()};expect(await service.insert(owner,op)).toMatchObject({state:'unknown'});expect(await service.insert(owner,op)).toMatchObject({state:'unknown'});expect(write).toHaveBeenCalledTimes(1);});
 it('expires prepared sources and rejects oversized or empty host text before transport',async()=>{const b=await service.bind(owner,input());now+=120001;await expect(service.insert(owner,{bindingId:b.id,operationId:randomUUID()})).rejects.toMatchObject({code:'CANCELED'});proof.text='x'.repeat(8001);await expect(service.bind(owner,input())).rejects.toMatchObject({code:'TOO_LARGE'});proof.text='\0';await expect(service.bind(owner,input())).rejects.toMatchObject({code:'TOO_LARGE'});expect(writes).toEqual([]);});
});
''')
(root/'src/renderer/features/applications/terminal-insertion.test.tsx').write_text(r'''// @vitest-environment jsdom
import {cleanup,fireEvent,render,screen,waitFor} from '@testing-library/react';
import {beforeEach,afterEach,describe,it,expect,vi} from 'vitest';
import {ApplicationTerminalButton} from './terminal-insertion';
const m=vi.hoisted(()=>({bind:vi.fn(),insert:vi.fn(),release:vi.fn(),open:vi.fn(),prepare:vi.fn(),focus:vi.fn(),close:vi.fn(),task:{id:'t1',projectId:'p1',ptyId:'pty1',title:'Explicit original task',archivedAt:null} as any,terminals:new Map([['t1','pty1']])}));
vi.mock('@renderer/lib/ipc',()=>({rpc:{applications:{terminalBind:m.bind,terminalInsert:m.insert,terminalRelease:m.release}},events:{on:()=>()=>{}}}));
vi.mock('@renderer/core/tasks-store',()=>({tasksStore:{get current(){return m.task;},terminals:m.terminals}}));
vi.mock('@renderer/core/navigation',()=>({navigation:{get currentViewId(){return 'task';},get currentTaskId(){return m.task?.id;},openTask:m.open,prepareApplicationTask:m.prepare}}));
vi.mock('@renderer/features/files/terminal-context/store',()=>({currentFileTerminal:()=>m.task?{taskId:m.task.id,ptyId:m.task.ptyId,focus:m.focus}:null}));
const source={kind:'skill' as const,appId:'mail' as const,skillId:'work-assistant'},binding={id:'binding1',taskId:'t1',ptyId:'pty1',projectId:'p1',runId:'run1',text:'host-resolved example',expiresAt:9999999999999};
const mount=()=>render(<ApplicationTerminalButton projectId="p1" source={source} onInserted={m.close} label="插入示例到终端"/>);
beforeEach(()=>{vi.clearAllMocks();m.task={id:'t1',projectId:'p1',ptyId:'pty1',title:'Explicit original task',archivedAt:null};m.terminals.clear();m.terminals.set('t1','pty1');m.bind.mockResolvedValue({ok:true,value:binding});m.insert.mockImplementation(async(input)=>({ok:true,value:{operationId:input.operationId,state:'inserted'}}));m.release.mockResolvedValue({ok:true,value:{released:true}});});
afterEach(()=>cleanup());
describe('explicit application target delivery UI',()=>{
 it('sends only a typed source to the captured task,focuses that terminal,and never calls a task launch',async()=>{mount();fireEvent.click(screen.getByRole('button',{name:/插入示例/}));await waitFor(()=>expect(m.focus).toHaveBeenCalledTimes(1));expect(m.bind).toHaveBeenCalledWith({projectId:'p1',target:{taskId:'t1',ptyId:'pty1'},source});expect(m.insert.mock.calls[0][0]).toMatchObject({bindingId:'binding1'});expect(m.close).toHaveBeenCalledTimes(1);expect(m.open).toHaveBeenCalledWith('t1');expect(m.prepare).not.toHaveBeenCalled();});
 it('does not choose a running task from another project and prepares a composer only on explicit action',async()=>{m.task.projectId='other';mount();expect(m.bind).not.toHaveBeenCalled();fireEvent.click(screen.getByRole('button',{name:/准备新任务/}));expect(m.prepare).toHaveBeenCalledWith('p1',expect.stringContaining('本地邮件'));expect(m.insert).not.toHaveBeenCalled();});
 it('does not rebind a detail to a replacement task or PTY after it was opened',()=>{const view=mount();m.task={...m.task,id:'t2',ptyId:'pty2'};m.terminals.set('t2','pty2');view.rerender(<ApplicationTerminalButton projectId="p1" source={source}/>);expect(screen.queryByRole('button',{name:/插入终端/})).toBeNull();expect(m.bind).not.toHaveBeenCalled();});
 it('releases late preparation after unmount without dispatching a paste or stealing focus',async()=>{let finish!:(v:unknown)=>void;m.bind.mockImplementation(()=>new Promise(r=>finish=r));const view=mount();fireEvent.click(screen.getByRole('button',{name:/插入示例/}));view.unmount();finish({ok:true,value:binding});await waitFor(()=>expect(m.release).toHaveBeenCalledWith('binding1'));expect(m.insert).not.toHaveBeenCalled();expect(m.focus).not.toHaveBeenCalled();});
 it('blocks repeated clicks and leaves an ambiguous result unknown without retry',async()=>{m.insert.mockResolvedValue({ok:true,value:{operationId:'mismatch',state:'inserted'}});mount();const button=screen.getByRole('button',{name:/插入示例/});fireEvent.click(button);fireEvent.click(button);await screen.findByText('插入结果未知；不会自动重发');expect(m.bind).toHaveBeenCalledTimes(1);expect(m.insert).toHaveBeenCalledTimes(1);expect(button).toHaveProperty('disabled',true);expect(m.focus).not.toHaveBeenCalled();});
});
''')
